import { describe, it, expect } from "vitest";
import { generateSidebar } from "@/sidebar-generator";
import type { DocsRoute } from "@/types";

function makeRoute(
  path: string,
  title: string,
  opts?: {
    sidebarPosition?: number;
    sidebarLabel?: string;
    relativePath?: string;
    isDirectoryIndex?: boolean;
  },
): DocsRoute {
  return {
    path,
    filePath: `/project/docs${path.replace("/docs", "")}.md`,
    pageData: {
      title,
      excerpt: "",
      headings: [],
      relativePath: opts?.relativePath || "",
      sidebarPosition: opts?.sidebarPosition,
      sidebarLabel: opts?.sidebarLabel,
    },
    isDirectoryIndex: opts?.isDirectoryIndex,
  };
}

